package gameoflife;

import java.util.Set;
import java.util.stream.Collectors;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return livingCells.stream()
                .filter(cell -> livingNeighbourCount(cell, livingCells) == 3)
                .collect(Collectors.toSet());
    }

    private int livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if ((dx != 0 || dy != 0)
                        && livingCells.contains(new Cell(cell.x() + dx, cell.y() + dy))) {
                    count++;
                }
            }
        }
        return count;
    }
}
EOF
